/** Keeps architecture, responsive, visual, interaction and UX verification independent. */
class Design_Core_Elementor_Visual_Quality_Gate{const VERSION=1;public function evaluate(array $dimensions,array $options=array()){$ref=!empty($options['reference_exists']);$interactive=!empty($options['interactive']);$n=array('architecture'=>$this->d($dimensions['architecture']??array(),true),'responsive'=>$this->d($dimensions['responsive']??array(),true),'visual'=>$this->d($dimensions['visual']??array(),$ref),'interaction'=>$this->d($dimensions['interaction']??array(),$interactive),'ux'=>$this->d($dimensions['ux']??array(),false));$blocking=array();$scores=array();foreach($n as $name=>$d){if($d['required']&&'pass'!==$d['status'])$blocking[]=$name.':'.$d['status'];if(is_numeric($d['score']))$scores[]=(float)$d['score'];}return array('version'=>1,'status'=>$blocking?'blocked':'pass','publishable'=>!$blocking,'score'=>$scores?round(array_sum($scores)/count($scores),2):null,'dimensions'=>$n,'blocking_reasons'=>$blocking,'rule'=>'A required dimension must be verified and pass. Unavailable or unverified is never promoted to pass.');}private function d($x,$required){$x=is_array($x)?$x:array();$s=strtolower((string)($x['status']??'unverified'));if(in_array($s,array('success','ok'),true))$s='pass';if(in_array($s,array('needs-correction','needs-rebuild','warning'),true))$s='fail';if(!in_array($s,array('pass','fail','unverified','unavailable','not-applicable'),true))$s='unverified';return array('status'=>$s,'required'=>(bool)$required,'score'=>isset($x['score'])?(float)$x['score']:(isset($x['similarity'])?round((float)$x['similarity']*100,2):null),'details'=>$x);}}
